javascript// PatternApp.jsx
import React, { useEffect, useState } from 'react';
import wasmModule from './pattern.wasm';

function PatternApp() {
    const [wasm, setWasm] = useState(null);
    const [scale, setScale] = useState(1.0);
    
    useEffect(() => {
        // Load WASM module
        WebAssembly.instantiate(wasmModule).then(setWasm);
    }, []);
    
    const generatePattern = () => {
        if (wasm) {
            const svgData = wasm.exports.generatePatternTile(
                512, 512, scale, rotation, colorSeed
            );
            renderToCanvas(svgData);
        }
    };
    
    return (
        <div className="pattern-app">
            <Canvas id="pattern-preview" />
            <Controls>
                <Slider value={scale} onChange={setScale} />
                <Button onClick={exportSVG}>Export</Button>
            </Controls>
        </div>
    );
}
