javascript// pattern-config-schema.js
const PATTERN_CONFIG_VERSION = "2.0";

// Config migration system
function migrateConfig(config) {
    switch(config.version) {
        case "1.0":
            // Migrate from 1.0 to 1.1
            config.features = config.features || {};
            config.version = "1.1";
            // Fall through to next migration
        
        case "1.1":
            // Migrate from 1.1 to 2.0
            config.palettes = convertOldPalettes(config.colors);
            delete config.colors;
            config.version = "2.0";
            break;
    }
    return config;
}

// When loading old patterns
const loadPattern = async (path) => {
    let config = JSON.parse(await fs.readFile(path));
    
    // Auto-migrate old configs!
    if (config.version !== PATTERN_CONFIG_VERSION) {
        config = migrateConfig(config);
        // Optionally save the migrated version
        await fs.writeFile(path, JSON.stringify(config, null, 2));
    }
    
    return config;
};
